<?php
require __DIR__ . '/auth.php'; requireLogin();
$user=currentUser(); $today=date('Y-m-d');
$stmt=$db->prepare('SELECT * FROM lunches WHERE user_id=? AND lunch_date=? ORDER BY meal_time ASC,id DESC');$stmt->execute([$_SESSION['user_id'],$today]);$lunches=$stmt->fetchAll();
$stmt=$db->prepare('SELECT COUNT(*) FROM lunches WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$totalAll=(int)$stmt->fetchColumn();
$stmt=$db->prepare('SELECT COUNT(DISTINCT lunch_date) FROM lunches WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$daysLogged=(int)$stmt->fetchColumn();$totalToday=count($lunches);
$schedule=[['08:00','09:00','Breakfast','Idli / dosa / chapati + egg','🍳'],['10:30','11:00','Morning Snack','Banana or another fruit','🍌'],['12:00','13:00','Lunch','Rice + vegetables + fish/chicken/egg/dal','🍚'],['16:30','17:00','Evening Snack','Milk + guava + peanuts/almonds','🥛'],['20:00','21:00','During Duty','2 boiled eggs + banana','🥚'],['22:15','22:45','Dinner','Rice + fish/egg/chicken + vegetables','🍛']];
function displayDate(string $iso):string{$t=strtotime($iso);return $t?date('d-m-Y',$t):$iso;} function displayTime(?string $iso):string{$t=$iso?strtotime($iso):false;return $t?date('h:i A',$t):'';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f172a"><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="assets/icon.svg"><title>Lunch Food Log</title><style>
:root{--bg:#f4f7fb;--card:#fff;--text:#0f172a;--muted:#64748b;--line:#e2e8f0;--blue:#2563eb;--soft:#eff6ff;--danger:#dc2626;--shadow:0 12px 32px rgba(15,23,42,.07)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#e0ecff,transparent 30%),var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,"Segoe UI",Arial,sans-serif}.container{width:min(100% - 18px,1050px);margin:auto;padding:10px 0 45px}.hero{background:linear-gradient(135deg,#0f172a,#1d4ed8);color:#fff;border-radius:24px;padding:22px;box-shadow:0 18px 45px rgba(29,78,216,.2)}.hero-top{display:flex;justify-content:space-between;gap:15px}.brand{display:flex;align-items:center;gap:14px}.app-logo{width:72px;height:72px;border-radius:18px;display:block;box-shadow:0 8px 20px rgba(0,0,0,.25);background:#0f172a}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.14em;font-weight:800;opacity:.7}.hero h1{margin:6px 0;font-size:30px}.hero p{margin:0;color:#dbeafe}.userbar{margin-top:17px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.userbar a,.userbar button{color:#fff;text-decoration:none;border:1px solid #ffffff33;background:#ffffff14;border-radius:10px;padding:9px 12px;font-weight:800;font-size:12px}.userbar form{display:inline}.userbar button{cursor:pointer}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:15px 0}.stat,.card{background:var(--card);border:1px solid var(--line);box-shadow:var(--shadow)}.stat{border-radius:16px;padding:15px}.stat strong{display:block;font-size:24px}.stat span{font-size:12px;color:var(--muted)}.card{border-radius:20px;padding:19px;margin-bottom:15px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.head h2{font-size:18px;margin:0}.head small{color:var(--muted)}.schedule{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.meal{display:flex;gap:11px;padding:13px;border:1px solid var(--line);border-radius:14px;background:#fbfdff}.icon{width:40px;height:40px;border-radius:11px;background:var(--soft);display:grid;place-items:center;font-size:20px}.meal-name{font-weight:800}.time{font-size:11px;color:var(--blue);font-weight:800;margin-top:3px}.foodhint{font-size:12px;color:var(--muted);margin-top:4px}label{display:block;font-size:12px;font-weight:800;margin:12px 0 6px}input,select,textarea,button{width:100%;font:inherit;border-radius:11px;padding:12px}input,select,textarea{border:1px solid #d6dde8;background:#fff}textarea{min-height:75px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.full{grid-column:1/-1}button.save{border:0;background:#0f172a;color:#fff;font-weight:800;margin-top:14px}.entries{display:grid;gap:9px}.entry{border:1px solid var(--line);border-radius:14px;padding:13px}.entrytop{display:flex;justify-content:space-between;gap:8px}.food{font-weight:800}.badge{font-size:10px;background:#eff6ff;color:#1d4ed8;padding:5px 8px;border-radius:99px;font-weight:800}.meta,.notes{font-size:12px;color:var(--muted);margin-top:6px}.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.action{text-decoration:none;text-align:center;padding:12px;border-radius:11px;border:1px solid var(--line);font-weight:800;color:var(--text)}.primary{background:#0f172a;color:#fff}.entry-actions{margin-top:9px;display:flex;gap:14px;justify-content:flex-end}.edit,.delete{font-size:11px;font-weight:800;text-decoration:none}.edit{color:var(--blue)}.delete{color:var(--danger)}.flash{padding:11px 14px;border-radius:11px;margin:12px 0;background:#ecfdf5;color:#166534;border:1px solid #bbf7d0;font-size:13px;font-weight:700}.notify{margin-top:11px;border:0;background:#eef2ff;color:#1e3a8a;font-weight:800}.help,.empty{font-size:12px;color:var(--muted);margin-top:8px}.footer{text-align:center;color:var(--muted);font-size:11px;margin-top:20px}@media(max-width:680px){.hero h1{font-size:25px}.app-logo{width:58px;height:58px;border-radius:15px}.schedule,.grid,.actions{grid-template-columns:1fr}.full{grid-column:auto}.stats{gap:7px}.stat{padding:12px}.stat strong{font-size:20px}}
</style></head><body><main class="container"><header class="hero"><div class="hero-top"><div class="brand"><img class="app-logo" src="assets/icon.svg" alt="Lunch Food Log app logo"><div><div class="eyebrow">Personal nutrition tracker</div><h1>Lunch Food Log</h1><p>Welcome, <?=h($user['name'])?>. Track meals and keep your reports organized.</p></div></div></div><div class="userbar"><span>👤 <?=h($user['email'])?></span><span><a href="profile.php">Profile</a> <form method="post" action="logout.php" style="display:inline"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><button type="submit">Logout</button></form></span></div></header><?php if(isset($_GET['saved'])):?><div class="flash">✓ Food entry saved successfully.</div><?php elseif(isset($_GET['updated'])):?><div class="flash">✓ Food entry updated successfully.</div><?php elseif(isset($_GET['deleted'])):?><div class="flash">✓ Food entry deleted.</div><?php elseif(isset($_GET['welcome'])):?><div class="flash">✓ Account created. Your food log is ready.</div><?php endif;?><section class="stats"><div class="stat"><strong><?=$totalToday?></strong><span>Entries today</span></div><div class="stat"><strong><?=$daysLogged?></strong><span>Days logged</span></div><div class="stat"><strong><?=$totalAll?></strong><span>Total entries</span></div></section><section class="card"><div class="head"><h2>⏰ Daily Food Timetable</h2><small>6 meal windows</small></div><div class="schedule"><?php foreach($schedule as $m):?><div class="meal"><div class="icon"><?=$m[4]?></div><div><div class="meal-name"><?=h($m[2])?></div><div class="time"><?=date('h:i A',strtotime($m[0]))?> – <?=date('h:i A',strtotime($m[1]))?></div><div class="foodhint"><?=h($m[3])?></div></div></div><?php endforeach;?></div><button class="notify" id="mealNotifyButton" type="button" onclick="enableMealReminders();">🔔 Enable Meal Notifications</button><div class="help">Browser reminders work while the dashboard is open.</div></section><section class="card"><div class="head"><h2>➕ Add Food Entry</h2><small>DD-MM-YYYY</small></div><form method="post" action="save.php" id="foodForm"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><div class="grid"><div><label>Date</label><input id="date_display" value="<?=h(displayDate($today))?>" placeholder="DD-MM-YYYY" inputmode="numeric" maxlength="10" required><input type="hidden" name="lunch_date" id="lunch_date" value="<?=h($today)?>"></div><div><label>Meal</label><select name="meal_type"><?php foreach($schedule as $m):?><option value="<?=h($m[2])?>" <?=$m[2]==='Lunch'?'selected':''?>><?=$m[4].' '.h($m[2])?></option><?php endforeach;?></select></div><div class="full"><label>Food Item</label><input name="food_item" maxlength="150" placeholder="e.g. Rice + Fish Curry" required></div><div><label>Quantity</label><input name="quantity" maxlength="80" placeholder="e.g. 1 plate"></div><div><label>Notes</label><input name="notes" maxlength="250" placeholder="Optional note"></div></div><button class="save">Save Food Entry</button></form></section><section class="card"><div class="head"><h2>Today's Entries</h2><small><?=h(displayDate($today))?></small></div><?php if(!$lunches):?><div class="empty">No food entries recorded today.</div><?php else:?><div class="entries"><?php foreach($lunches as $item):?><article class="entry"><div class="entrytop"><div class="food"><?=h($item['food_item'])?></div><div class="badge"><?=h($item['meal_type']??'Lunch')?></div></div><div class="meta">📅 <?=h(displayDate($item['lunch_date']))?> · ⏰ <?=h($item['meal_time']??'')?> · <?=h(displayTime($item['recorded_time']??''))?></div><?php if($item['quantity']):?><div class="meta"><strong>Quantity:</strong> <?=h($item['quantity'])?></div><?php endif;?><?php if($item['notes']):?><div class="notes">📝 <?=h($item['notes'])?></div><?php endif;?><div class="entry-actions"><a class="edit" href="edit.php?id=<?=urlencode($item['id'])?>">Edit</a><form method="post" action="delete.php" onsubmit="return confirm('Delete this food entry?');"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="id" value="<?=h($item['id'])?>"><button class="delete" style="padding:0;border:0;background:none;width:auto;margin:0">Delete</button></form></div></article><?php endforeach;?></div><?php endif;?></section><section class="card"><div class="head"><h2>Quick Access</h2></div><div class="actions"><a class="action primary" href="reports.php">📊 Reports</a><a class="action" href="reports.php?report=monthly">📅 Monthly</a><a class="action" href="profile.php">👤 Profile</a></div></section><div class="footer">Lunch Food Log · Secure account system · Dates displayed as DD-MM-YYYY</div></main><div id="mealAlertBanner" class="alert-banner"></div><script src="assets/meal-alert.js"></script><script>function isoFromDisplay(v){const m=v.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!m)return null;const d=+m[1],mo=+m[2],y=+m[3],x=new Date(Date.UTC(y,mo-1,d));return x.getUTCFullYear()==y&&x.getUTCMonth()==mo-1&&x.getUTCDate()==d?`${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`:null}document.getElementById('foodForm').addEventListener('submit',function(e){const iso=isoFromDisplay(document.getElementById('date_display').value);if(!iso){e.preventDefault();alert('Please enter a valid date in DD-MM-YYYY format.');return}document.getElementById('lunch_date').value=iso});</script></body></html>
